-- User Service initial schema (docs/user/data.md).
--
-- The schema name is a reserved word, so it is quoted everywhere. Addresses,
-- preferences and deletions all key on the user id Auth published; ids are
-- generated by the application and timestamps are TIMESTAMPTZ in UTC.

CREATE SCHEMA IF NOT EXISTS "user";

CREATE OR REPLACE FUNCTION "user".set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

-- user_profiles.id is the user_id of the Auth account (USER-INV-006), which is
-- why the column has no default: the application always supplies it.
CREATE TABLE "user".user_profiles (
    id UUID PRIMARY KEY,

    first_name VARCHAR(100),
    last_name VARCHAR(100),
    date_of_birth DATE,
    gender VARCHAR(10) NOT NULL DEFAULT 'UNKNOWN',

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT chk_user_profiles_gender
        CHECK (gender IN ('MALE', 'FEMALE', 'OTHER', 'UNKNOWN')),

    -- A blank name is stored as NULL, never as an empty string, so the API can
    -- tell "not filled in" from "filled in with nothing".
    CONSTRAINT chk_user_profiles_first_name
        CHECK (first_name IS NULL OR btrim(first_name) <> ''),

    CONSTRAINT chk_user_profiles_last_name
        CHECK (last_name IS NULL OR btrim(last_name) <> '')
);

-- date_of_birth must not be in the future. That rule cannot become a CHECK
-- constraint because CURRENT_DATE is not immutable, so the application enforces
-- it (docs/user/data.md §3).

CREATE TRIGGER trg_user_profiles_set_updated_at
BEFORE UPDATE ON "user".user_profiles
FOR EACH ROW
EXECUTE FUNCTION "user".set_updated_at();

CREATE TABLE "user".user_addresses (
    id UUID PRIMARY KEY,

    user_id UUID NOT NULL,

    is_default BOOLEAN NOT NULL DEFAULT FALSE,

    recipient_name VARCHAR(200) NOT NULL,
    -- E.164; the profile itself holds no phone number.
    recipient_phone VARCHAR(16) NOT NULL,
    address_line VARCHAR(500) NOT NULL,

    -- Vietnamese administrative codes shared with Checkout, Order and
    -- Inventory. Deliveries are domestic only, so there is no country code.
    province_code VARCHAR(20) NOT NULL,
    district_code VARCHAR(20) NOT NULL,
    ward_code VARCHAR(20) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- The cascade is a safety net for the retention purge; the deletion
    -- consumer removes these rows at anonymization time.
    CONSTRAINT fk_user_addresses_user
        FOREIGN KEY (user_id) REFERENCES "user".user_profiles(id) ON DELETE CASCADE,

    CONSTRAINT chk_user_addresses_recipient_name
        CHECK (btrim(recipient_name) <> ''),

    CONSTRAINT chk_user_addresses_address_line
        CHECK (btrim(address_line) <> ''),

    CONSTRAINT chk_user_addresses_recipient_phone
        CHECK (recipient_phone ~ '^\+[1-9][0-9]{7,14}$'),

    CONSTRAINT chk_user_addresses_area_codes
        CHECK (
            province_code ~ '^[A-Za-z0-9_-]+$'
            AND district_code ~ '^[A-Za-z0-9_-]+$'
            AND ward_code ~ '^[A-Za-z0-9_-]+$'
        )
);

-- At most one default address per profile (USER-BR-003). This index is the last
-- guard: the application serializes the address book of one user first.
CREATE UNIQUE INDEX uq_user_addresses_one_default
    ON "user".user_addresses (user_id)
    WHERE is_default;

-- The address book is read in checkout order: default first, newest after.
CREATE INDEX idx_user_addresses_book
    ON "user".user_addresses (user_id, is_default DESC, created_at DESC);

CREATE TRIGGER trg_user_addresses_set_updated_at
BEFORE UPDATE ON "user".user_addresses
FOR EACH ROW
EXECUTE FUNCTION "user".set_updated_at();

CREATE TABLE "user".user_preferences (
    user_id UUID PRIMARY KEY,

    -- The platform ships one language and one currency; both are read-only in
    -- the API and are deliberately not published in any event.
    language VARCHAR(10) NOT NULL DEFAULT 'vi',
    currency VARCHAR(3) NOT NULL DEFAULT 'VND',

    -- The only three fields Notification Service replicates.
    email_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    in_app_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    marketing_enabled BOOLEAN NOT NULL DEFAULT TRUE,

    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_user_preferences_user
        FOREIGN KEY (user_id) REFERENCES "user".user_profiles(id) ON DELETE CASCADE,

    CONSTRAINT chk_user_preferences_language CHECK (language = 'vi'),
    CONSTRAINT chk_user_preferences_currency CHECK (currency = 'VND')
);

-- updated_at moves only when a preference actually changed, so a repeated PUT
-- of the same body cannot make a consumer think it received a newer snapshot.
CREATE TRIGGER trg_user_preferences_set_updated_at
BEFORE UPDATE ON "user".user_preferences
FOR EACH ROW
WHEN (
    OLD.email_enabled IS DISTINCT FROM NEW.email_enabled
    OR OLD.in_app_enabled IS DISTINCT FROM NEW.in_app_enabled
    OR OLD.marketing_enabled IS DISTINCT FROM NEW.marketing_enabled
)
EXECUTE FUNCTION "user".set_updated_at();

-- The retention record has no foreign key on purpose: it has to outlive the
-- profile row the purge worker deletes, and one row means "anonymized, waiting
-- to be purged" (docs/user/data.md §2).
CREATE TABLE "user".user_deletions (
    id UUID PRIMARY KEY,

    user_id UUID NOT NULL,

    deleted_at TIMESTAMPTZ NOT NULL,
    -- The deadline Auth published. User never recomputes it (USER-BR-007).
    hard_delete_after TIMESTAMPTZ NOT NULL,
    reason VARCHAR(50) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Business-key idempotency: a duplicate USER_DELETED is a no-op.
    CONSTRAINT uq_user_deletions_user_id UNIQUE (user_id),

    CONSTRAINT chk_user_deletions_reason
        CHECK (reason IN ('GDPR_REQUEST', 'ADMIN_DELETION')),

    CONSTRAINT chk_user_deletions_deadline
        CHECK (hard_delete_after > deleted_at)
);

-- A plain B-tree index: the worker supplies the cutoff, so the index must not
-- depend on NOW().
CREATE INDEX idx_user_deletions_hard_delete_after
    ON "user".user_deletions (hard_delete_after);
